/**
 * A small builder, encoder and simulator for TapeOut circuits (TAP-02 netlist format).
 *
 * Signals: 0 is constant 0, 1 is constant 1, 2..2+nIn-1 are the inputs, then every element adds the
 * signal it produces, in order. The last nOut signals are the outputs. A NAND may only read signals
 * that exist before it; a LATCH may read any signal and outputs its stored state (one-beat delay).
 * Inputs, outputs and state are packed LSB first (bit i is bit i%8 of byte i/8).
 */

export const NAND = 0x00;
export const LATCH = 0x01;

export type Sig = number;
